    /* Legacy color-variant block (kept as requested) */
    .variant-card {
      padding: 40px;
      border-radius: 8px;
      display: flex;
      flex-direction: column;
      align-items: center;
      border: 1px solid #eee;
      background-color: transparent;
      transition: transform 0.2s ease;
    }

    .variant-card:hover {
      transform: translateY(-2px);
    }

    .variant-card.dark-mode {
      background-color: #1a1a1a;
      border: none;
    }

    .variant-card svg {
      height: 64px;
      width: auto;
      display: block;
      margin: 0 auto;
    }

    .variant-label {
      font-size: 12px;
      margin-top: 15px;
      font-weight: 600;
      color: #666;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      text-align: center;
    }

    .variant-card.dark-mode .variant-label {
      color: #ffffff;
    }

    .favicon-size-grid {
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 20px;
      margin-top: 20px;
    }

    .favicon-size-card {
      border: 1px solid #e9e9e9;
      border-radius: 10px;
      background: #ffffff;
      padding: 16px;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 10px;
      min-height: 215px;
    }

    .favicon-size-preview {
      width: 100%;
      aspect-ratio: 1 / 1;
      border-radius: 10px;
      background: #f4f4f4;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .favicon-size-preview.cream {
      background: #f5f1e8;
    }

    .favicon-size-mark {
      display: block;
    width: 100%;  
    height: auto;
    }

    .favicon-size-label {
      font-size: 12px;
      font-weight: 500;
      color: #444;
      text-align: center;
      line-height: 1.25;
    }

    @media (max-width: 1200px) {
      .favicon-size-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }
    }

    @media (max-width: 768px) {
      .favicon-size-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 520px) {
      .favicon-size-grid {
        grid-template-columns: 1fr;
      }
    }
  </style>

